"""Build bilingual offline graph, evidence bundle and print diagrams from one model."""
from pathlib import Path
import json, hashlib, datetime, math, csv
R=Path(__file__).resolve().parents[1]
OUT=R/'ui/epistemic'; OUT.mkdir(parents=True,exist_ok=True)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def bi(es,en):return {'es':es,'en':en}
def load(p):return json.loads((R/p).read_text())
A='research/revision_v17/results/audit.json'; C='research/revision_v17/results/cassini.json'; I='research/revision_v18/results/information_audit.json'; D='research/dcae_frontier/results/REANALYSIS.json'; P='research/results/physical_checks.json'; M='research/results/mond_quadrupole.json'; G='research/results/gaia_covariance.json'
c,a,i,d,p,m=map(load,[C,A,I,D,P,M])
nodes=[];edges=[];artifacts={}
def artifact(path):
 f=R/path
 if not f.is_file():raise FileNotFoundError(path)
 if path not in artifacts:
  raw=f.read_bytes();artifacts[path]={'path':path,'sha256':sha(f),'bytes':len(raw),'text':raw.decode()}
 return path
def node(id,route,col,title,summary,formula,status,kind,files,limits,metrics=None):
 nodes.append(dict(id=id,route=route,column=col,title=bi(*title),summary=bi(*summary),formula=formula,status=status,evidence_class=kind,artifacts=[artifact(f) for f in files],limits=bi(*limits),metrics=metrics or {}))
